function getVar(name) {
  if (typeof $vars !== 'undefined' && $vars[name] != null && String($vars[name]).trim()) {
    return String($vars[name]).trim();
  }
  return '';
}
const expected = getVar('N8N_WEBHOOK_TOKEN');
if (!expected) throw new Error('N8N_WEBHOOK_TOKEN is not set in n8n Variables');
const req = $input.first().json || {};
const headers = req.headers || {};
const auth = String(headers.authorization || headers.Authorization || '').trim();
const token = auth.toLowerCase().startsWith('bearer ') ? auth.slice(7).trim() : auth;
if (!token || token !== expected) throw new Error('Unauthorized');
return $input.all();

const postId = $('Publish Request').first().json.body.postId || '';
const raw = $input.first().json;
if (raw && raw.success === false) {
  throw new Error((raw.error || 'Failed to load social post') + ' postId=' + postId);
}
const row = raw && raw.data ? raw.data : raw;
if (!row || !row.id) throw new Error('Draft post not found postId=' + postId);
return [{ json: {
  id: row.id,
  captions: row.captions || {},
  composed_captions: row.composed_captions || {},
  platforms: row.platforms || [],
  mediaUrl: row.media_signed_url || row.mediaUrl || null,
  postId: row.id
} }];

const post = $('Flatten Post Data').first().json;
const resp = $input.first().json;
if (resp && resp.success === false) {
  throw new Error((resp.error || 'Failed to fetch social credentials') + ' postId=' + post.id);
}
const creds = Array.isArray(resp?.data) ? resp.data : [];
const platforms = post.platforms || [];
const composed = post.composed_captions || {};
const captions = post.captions || {};
const mediaUrl = post.mediaUrl;
const postId = post.id;
const SUPPORTED = ['instagram', 'facebook', 'x', 'linkedin'];
const items = [];
for (const platform of platforms) {
  if (!SUPPORTED.includes(platform)) continue;
  const cred = creds.find(c => c.platform === platform);
  if (!cred) continue;
  const caption = composed[platform] || (captions[platform] && captions[platform].caption) || '';
  items.push({ json: {
    platform,
    caption,
    platformToken: cred.access_token,
    mediaUrl,
    postId
  }});
}
if (items.length === 0) throw new Error('No connected platform credentials for requested platforms postId=' + postId);
return items;

const item = $input.first().json;
const platform = item.platform;
const token = item.platformToken;
const caption = item.caption || '';
const mediaUrl = item.mediaUrl;
const helpers = this.helpers;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const remember = (result) => {
  const staticData = $getWorkflowStaticData('global');
  if (!Array.isArray(staticData.publishResults)) staticData.publishResults = [];
  staticData.publishResults.push(result);
  return [{ json: result }];
};

try {
  if (platform === 'facebook') {
    const pages = await helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.facebook.com/v21.0/me/accounts?fields=id,name,access_token',
      headers: { Authorization: `Bearer ${token}` },
      json: true,
    });
    const page = (pages.data || [])[0];
    if (!page || !page.id) throw new Error('No Facebook page linked to token');
    const pageToken = page.access_token || token;
    let res;
    if (mediaUrl) {
      res = await helpers.httpRequest({
        method: 'POST',
        url: `https://graph.facebook.com/v21.0/${page.id}/photos`,
        headers: { Authorization: `Bearer ${pageToken}` },
        body: { url: mediaUrl, caption },
        json: true,
      });
    } else {
      res = await helpers.httpRequest({
        method: 'POST',
        url: `https://graph.facebook.com/v21.0/${page.id}/feed`,
        headers: { Authorization: `Bearer ${pageToken}` },
        body: { message: caption },
        json: true,
      });
    }
    return remember({ platform, success: true, provider_id: res.id || res.post_id || null });
  }

  if (platform === 'instagram') {
    const pages = await helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.facebook.com/v21.0/me/accounts?fields=instagram_business_account',
      headers: { Authorization: `Bearer ${token}` },
      json: true,
    });
    const page = (pages.data || []).find(p => p.instagram_business_account && p.instagram_business_account.id);
    const igUserId = page && page.instagram_business_account && page.instagram_business_account.id;
    if (!igUserId) throw new Error('No instagram_business_account linked to token');
    if (!mediaUrl) throw new Error('Instagram publish requires mediaUrl');
    const container = await helpers.httpRequest({
      method: 'POST',
      url: `https://graph.facebook.com/v21.0/${igUserId}/media`,
      headers: { Authorization: `Bearer ${token}` },
      body: { caption, image_url: mediaUrl },
      json: true,
    });
    const creationId = container.id;
    if (!creationId) throw new Error('IG media container creation failed');
    let status = 'IN_PROGRESS';
    for (let i = 0; i < 12; i++) {
      await sleep(5000);
      const st = await helpers.httpRequest({
        method: 'GET',
        url: `https://graph.facebook.com/v21.0/${creationId}?fields=status_code`,
        headers: { Authorization: `Bearer ${token}` },
        json: true,
      });
      status = st.status_code || status;
      if (status === 'FINISHED') break;
      if (status === 'ERROR' || status === 'EXPIRED') throw new Error('IG media container ' + status);
    }
    if (status !== 'FINISHED') throw new Error('IG media container did not finish in time');
    const published = await helpers.httpRequest({
      method: 'POST',
      url: `https://graph.facebook.com/v21.0/${igUserId}/media_publish`,
      headers: { Authorization: `Bearer ${token}` },
      body: { creation_id: creationId },
      json: true,
    });
    return remember({ platform, success: true, provider_id: published.id || creationId });
  }

  if (platform === 'x') {
    let text = caption;
    if (mediaUrl && (text + ' ' + mediaUrl).length <= 280) {
      text = text ? (text + ' ' + mediaUrl) : mediaUrl;
    }
    const res = await helpers.httpRequest({
      method: 'POST',
      url: 'https://api.twitter.com/2/tweets',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: { text },
      json: true,
    });
    return remember({ platform, success: true, provider_id: (res.data && res.data.id) || null });
  }

  if (platform === 'linkedin') {
    let personId = null;
    try {
      const me = await helpers.httpRequest({
        method: 'GET',
        url: 'https://api.linkedin.com/v2/userinfo',
        headers: { Authorization: `Bearer ${token}` },
        json: true,
      });
      personId = me.sub || me.id || null;
    } catch (e) {
      const me = await helpers.httpRequest({
        method: 'GET',
        url: 'https://api.linkedin.com/v2/me',
        headers: { Authorization: `Bearer ${token}` },
        json: true,
      });
      personId = me.id || null;
    }
    if (!personId) throw new Error('Could not resolve LinkedIn member id');
    const author = String(personId).startsWith('urn:') ? personId : ('urn:li:person:' + personId);
    const shareContent = {
      shareCommentary: { text: caption },
      shareMediaCategory: mediaUrl ? 'ARTICLE' : 'NONE',
    };
    if (mediaUrl) {
      shareContent.media = [{ status: 'READY', originalUrl: mediaUrl }];
    }
    const share = {
      author,
      lifecycleState: 'PUBLISHED',
      specificContent: { 'com.linkedin.ugc.ShareContent': shareContent },
      visibility: { 'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC' },
    };
    const res = await helpers.httpRequest({
      method: 'POST',
      url: 'https://api.linkedin.com/v2/ugcPosts',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
        'X-Restli-Protocol-Version': '2.0.0',
      },
      body: share,
      json: true,
    });
    return remember({ platform, success: true, provider_id: res.id || null });
  }

  throw new Error('Unsupported platform: ' + platform);
} catch (error) {
  return remember({ platform, success: false, error: error.message || String(error) });
}

const postId = $('Publish Request').first().json.body.postId;
const staticData = $getWorkflowStaticData('global');
const stored = Array.isArray(staticData.publishResults) ? staticData.publishResults : [];
const results = stored.length ? stored : $('Publish Platform').all().map(i => i.json);
staticData.publishResults = [];
const failures = results.filter(r => !r.success);
const appUrl = ($vars.NEXUS_APP_URL || 'https://nexusos.knurdz.org').replace(/\/$/, '');
const token = ($vars.N8N_INGEST_TOKEN || $vars.N8N_BOOTSTRAP_TOKEN || '').trim();
if (!token) throw new Error('N8N_INGEST_TOKEN not configured postId=' + postId);
const status = failures.length ? 'failed' : 'published';
const error = failures.map(f => `${f.platform}: ${f.error || 'failed'}`).join('; ') || null;
await this.helpers.httpRequest({
  method: 'POST',
  url: `${appUrl}/api/internal/n8n/post-result`,
  headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
  body: { postId, status, error },
  json: true,
});
return [{ json: { postId, status, platforms: results } }];

function getVar(name) {
  if (typeof $vars !== 'undefined' && $vars[name] != null && String($vars[name]).trim()) {
    return String($vars[name]).trim();
  }
  return '';
}
const payload = $input.first().json || {};
const msg = String((payload.execution && payload.execution.error && payload.execution.error.message) || payload.message || '');
const uuidMatch = msg.match(/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/i);
const postId = uuidMatch ? uuidMatch[0] : null;
if (!postId) {
  return [{ json: { skipped: true, reason: 'no postId in error' } }];
}
const appUrl = (getVar('NEXUS_APP_URL') || 'https://nexusos.knurdz.org').replace(/\/$/, '');
const token = (getVar('N8N_INGEST_TOKEN') || getVar('N8N_BOOTSTRAP_TOKEN') || '').trim();
if (!token) throw new Error('N8N_INGEST_TOKEN not configured');
await this.helpers.httpRequest({
  method: 'POST',
  url: `${appUrl}/api/internal/n8n/post-result`,
  headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
  body: { postId, status: 'failed', error: (msg || 'publish workflow failed').slice(0, 500) },
  json: true,
});
return [{ json: { postId, status: 'failed' } }];
